  'Facebook displays cover photos at 820×312 px on computers. On smartphones, Facebook displays a centered 640×360 crop, clipping the left and right ~90 px. Center your text and subjects inside the 640 px mobile safe zone.':
    [
      'Facebook muestra fotos de portada a 820×312 px en las computadoras. En los teléfonos inteligentes, Facebook muestra un recorte centrado de 640×360, recortando la izquierda y la derecha ~90 px. Centre su texto y asuntos dentro de la zona segura móvil de 640 px.',
      "Facebook visualizza le foto di copertina a 820×312 px sui computer. Sugli smartphone, Facebook visualizza un ritaglio centrato di 640×360, ritagliando i ~90 px sinistro e destro. Centrare il testo e gli oggetti all'interno della zona sicura mobile da 640 px.",
      'Facebook zeigt Titelfotos auf Computern mit 820 x 312 Pixeln an. Auf Smartphones zeigt Facebook einen zentrierten 640×360-Ausschnitt an, wobei links und rechts etwa 90 Pixel abgeschnitten werden. Zentrieren Sie Ihren Text und Ihre Betreffzeilen innerhalb der 640-Pixel-Sicherheitszone für Mobilgeräte.',
      'O Facebook exibe fotos de capa em 820×312 px em computadores. Em smartphones, o Facebook exibe um corte centralizado de 640×360, cortando a esquerda e a direita em aproximadamente 90 px. Centralize seu texto e assuntos dentro da zona segura móvel de 640 px.',
      "Facebook affiche des photos de couverture à 820 × 312 px sur les ordinateurs. Sur les smartphones, Facebook affiche un recadrage centré de 640×360, découpant la gauche et la droite d'environ 90 px. Centrez votre texte et vos sujets dans la zone de sécurité mobile de 640 px.",
    ],
