  'Standard blur or pixelation can sometimes be partially reconstructed or unblurred by computer vision tools. Solid redaction permanently burns 100% opaque color rectangles into the exported image, so sensitive data (passwords, credit cards, personal information) cannot be recovered.':
    [
      'En ocasiones, el desenfoque o el pixelado estándar se pueden reconstruir parcialmente o eliminar el desenfoque mediante herramientas de visión por computadora. La redacción sólida graba permanentemente rectángulos de color 100% opacos en la imagen exportada, por lo que los datos confidenciales (contraseñas, tarjetas de crédito, información personal) no se pueden recuperar.',
      "La sfocatura o la pixelizzazione standard a volte possono essere parzialmente ricostruite o non sfocate dagli strumenti di visione artificiale. La redazione solida brucia in modo permanente rettangoli di colore opaco al 100% nell'immagine esportata, quindi i dati sensibili (password, carte di credito, informazioni personali) non possono essere recuperati.",
      'Standardmäßige Unschärfe oder Pixelung können manchmal durch Computer-Vision-Tools teilweise rekonstruiert oder unscharf gemacht werden. Durch die solide Schwärzung werden dauerhaft 100 % undurchsichtige Farbrechtecke in das exportierte Bild eingebrannt, sodass vertrauliche Daten (Passwörter, Kreditkarten, persönliche Daten) nicht wiederhergestellt werden können.',
      'O desfoque ou pixelização padrão às vezes pode ser parcialmente reconstruído ou desfocado por ferramentas de visão computacional. A redação sólida grava permanentemente retângulos de cores 100% opacas na imagem exportada, de forma que dados confidenciais (senhas, cartões de crédito, informações pessoais) não possam ser recuperados.',
      "Le flou ou la pixellisation standard peut parfois être partiellement reconstruit ou supprimé par les outils de vision par ordinateur. Une rédaction solide grave en permanence des rectangles de couleur 100 % opaques dans l'image exportée, de sorte que les données sensibles (mots de passe, cartes de crédit, informations personnelles) ne peuvent pas être récupérées.",
    ],
