  'Documents are rendered on your device at 2Ã resolution for crisp text. Fonts not installed on your device will fall back to standard system fonts. Complex Word macros or external links are ignored for security and privacy.':
    [
      'Los documentos se procesan en su dispositivo con una resolución de 2× para obtener un texto nítido. Las fuentes que no estén instaladas en su dispositivo recurrirán a las fuentes estándar del sistema. Las macros complejas de Word o los enlaces externos se ignoran por motivos de seguridad y privacidad.',
      'I documenti vengono visualizzati sul tuo dispositivo con una risoluzione di 2× per un testo nitido. I caratteri non installati sul tuo dispositivo torneranno ai caratteri di sistema standard. Le macro complesse di Word o i collegamenti esterni vengono ignorati per motivi di sicurezza e privacy.',
      'Dokumente werden auf Ihrem Gerät mit einer Auflösung von 2× für gestochen scharfen Text gerendert. Schriftarten, die nicht auf Ihrem Gerät installiert sind, werden auf Standard-Systemschriftarten zurückgegriffen. Komplexe Word-Makros oder externe Links werden aus Sicherheits- und Datenschutzgründen ignoriert.',
      'Os documentos são renderizados em seu dispositivo com resolução de 2× para texto nítido. As fontes não instaladas no seu dispositivo voltarão às fontes padrão do sistema. Macros complexas do Word ou links externos são ignorados por questões de segurança e privacidade.',
      'Les documents sont rendus sur votre appareil à une résolution de 2 × pour un texte net. Les polices non installées sur votre appareil reviendront aux polices système standard. Les macros Word complexes ou les liens externes sont ignorés pour des raisons de sécurité et de confidentialité.',
    ],
