  'This is regular paragraph text demonstrating readability under current lighting and contrast conditions. Good contrast ensures that all users, including those with moderate low vision, can read content without difficulty.':
    [
      'Este es un texto de párrafo normal que demuestra legibilidad en las condiciones actuales de iluminación y contraste. Un buen contraste garantiza que todos los usuarios, incluidos aquellos con baja visión moderada, puedan leer el contenido sin dificultad.',
      'Questo è un normale testo di paragrafo che dimostra la leggibilità nelle attuali condizioni di illuminazione e contrasto. Un buon contrasto garantisce che tutti gli utenti, compresi quelli con ipovisione moderata, possano leggere i contenuti senza difficoltà.',
      'Dies ist ein normaler Absatztext, der die Lesbarkeit unter den aktuellen Licht- und Kontrastbedingungen demonstriert. Ein guter Kontrast stellt sicher, dass alle Benutzer, auch diejenigen mit mäßiger Sehbehinderung, Inhalte problemlos lesen können.',
      'Este é um texto de parágrafo normal que demonstra legibilidade sob condições atuais de iluminação e contraste. Um bom contraste garante que todos os usuários, inclusive aqueles com baixa visão moderada, possam ler o conteúdo sem dificuldade.',
      "Il s'agit d'un texte de paragraphe standard démontrant la lisibilité dans les conditions d'éclairage et de contraste actuelles. Un bon contraste garantit que tous les utilisateurs, y compris ceux ayant une basse vision modérée, peuvent lire le contenu sans difficulté.",
    ],
