  'vector paths, grouping identical neighboring pixels and maintaining alpha transparency. Scalable to any size without blur; ideal for pixel art, sprites, logos, and retro graphics (bounded to 128Ã128 max for high performance).':
    [
      'rutas vectoriales, agrupando píxeles vecinos idénticos y manteniendo la transparencia alfa. Escalable a cualquier tamaño sin desenfoque; ideal para pixel art, sprites, logotipos y gráficos retro (limitados a 128×128 máximo para un alto rendimiento).',
      'percorsi vettoriali, raggruppando pixel vicini identici e mantenendo la trasparenza alfa. Scalabile a qualsiasi dimensione senza sfocatura; ideale per pixel art, sprite, loghi e grafica retrò (limitato a 128×128 max per prestazioni elevate).',
      'Vektorpfade, Gruppierung identischer benachbarter Pixel und Beibehaltung der Alpha-Transparenz. Ohne Unschärfe auf jede Größe skalierbar; Ideal für Pixelkunst, Sprites, Logos und Retro-Grafiken (begrenzt auf maximal 128 x 128 für hohe Leistung).',
      'caminhos vetoriais, agrupando pixels vizinhos idênticos e mantendo a transparência alfa. Escalável para qualquer tamanho sem desfoque; ideal para pixel art, sprites, logotipos e gráficos retrô (limitado a 128x128 no máximo para alto desempenho).',
      'chemins vectoriels, regroupant les pixels voisins identiques et conservant la transparence alpha. Extensible à n’importe quelle taille sans flou ; idéal pour le pixel art, les sprites, les logos et les graphiques rétro (limité à 128 × 128 max pour des performances élevées).',
    ],
